span.span:
## Tool schemas (Bedrock toolConfig)

{

 "search_flights": {

   "name": "search_flights",

   "description": "Search for flights between two cities.",

   "parameters": {

    "type": "object",

    "properties": {

      "departure_city": {"type": "string", "description": "The city to depart from"},

      "arrival_city": {"type": "string", "description": "The destination city"},

      "trip_type": {"type": "string", "enum": ["one_way", "round_trip"], "description": "Type of trip"},

      "max_price": {"type": "number", "description": "Maximum price filter"},

      "sort_by": {"type": "string", "enum": ["price", "departure_time"], "description": "Sort results by this field"},

      "top_k": {"type": "integer", "description": "Number of results to return (default 10)"}

    },

    "required": ["departure_city", "arrival_city", "trip_type"]

   }

 },

 "search_hotels": {

   "name": "search_hotels",

   "description": "Search for hotels in one or multiple cities. Use comma-separated cities for batch query.",

   "parameters": {

    "type": "object",

    "properties": {

      "city": {"type": "string", "description": "City or comma-separated cities (e.g., ’Paris’ or ’Paris,London,Tokyo’)"},

      "name": {"type": "string", "description": "Look up a SPECIFIC hotel by name -- the only reliable way to confirm an exact hotel exists, since a browse returns only top_k rows"},

      "max_price": {"type": "number", "description": "Maximum price per night"},

      "min_star": {"type": "integer", "description": "Minimum star rating (1-5)"},

      "amenity": {"type": "string", "description": "Semantic search for amenities"},

      "sort_by": {"type": "string", "enum": ["price", "rating", "star"], "description": "Sort results by this field"},

      "top_k": {"type": "integer", "description": "Number of results per city (default 10)"}

    },

    "required": ["city"]

   }

 },

 "search_attractions": {

   "name": "search_attractions",

   "description": "Search for attractions in one or multiple cities. Use comma-separated cities for batch query.",

   "parameters": {

    "type": "object",

    "properties": {

      "city": {"type": "string", "description": "City or comma-separated cities"},

      "attraction_name": {"type": "string", "description": "Look up a SPECIFIC attraction by name -- absence from a browse listing does NOT mean it is missing"},

      "max_ticket_price": {"type": "number", "description": "Maximum ticket price"},

      "facility": {"type": "string", "description": "Semantic search for facilities"},

      "sort_by": {"type": "string", "enum": ["price", "rating", "duration_of_visit"], "description": "Sort results by this field"},

      "top_k": {"type": "integer", "description": "Number of results per city (default 10)"}

    },

    "required": ["city"]

   }

 },

 "search_cars": {

   "name": "search_cars",

   "description": "Search for rental cars in one or multiple cities. Use comma-separated cities for batch query.",

   "parameters": {

    "type": "object",

    "properties": {

      "city": {"type": "string", "description": "City or comma-separated cities"},

      "min_capacity": {"type": "integer", "description": "Minimum passenger capacity"},

      "max_price_per_day": {"type": "number", "description": "Maximum price per day"},

      "car_type": {"type": "string", "description": "Type of car"},

      "extra_service": {"type": "string", "description": "Semantic search for extra services"},

      "top_k": {"type": "integer", "description": "Number of results per city (default 10)"}

    },

    "required": ["city"]

   }

 },

 "compute_travel_time": {

   "name": "compute_travel_time",

   "description": "FREE (does NOT count against the 15-search budget). Distance + the MINIMUM door-to-door minutes the feasibility check (B3) requires between two locations -- the exact model the scorer uses. Identify each endpoint by _latitude/_longitude from a search result, or by _name/_city/_type.",

   "parameters": {

    "type": "object",

    "properties": {

      "from_name": {"type": "string"}, "from_city": {"type": "string"},

      "from_type": {"type": "string", "enum": ["attraction", "hotel", "flight"]},

      "from_latitude": {"type": "number"}, "from_longitude": {"type": "number"},

      "to_name": {"type": "string"}, "to_city": {"type": "string"},

      "to_type": {"type": "string", "enum": ["attraction", "hotel", "flight"]},

      "to_latitude": {"type": "number"}, "to_longitude": {"type": "number"}

    },

    "required": []

   }

 },

 "write_note": {

   "name": "write_note",

   "description": "FREE (does NOT count against the search budget). Jot a short note to your planning notebook (a chosen flight+times, a day-to-city assignment, an opening-hours constraint). You will see all your notes again at final-planning time.",

   "parameters": {

    "type": "object",

    "properties": {"text": {"type": "string", "description": "The note to remember."}},

    "required": ["text"]

   }

 },

 "submit_plan": {

   "name": "submit_plan",

   "description": "Submit the final travel plan, or a refusal for a genuinely impossible task.",

   "parameters": {

    "type": "object",

    "properties": {

      "is_feasible": {"type": "boolean", "description": "Whether the travel plan is feasible"},

      "refusal_reason": {"type": "string", "description": "Reason for refusal if not feasible"},

      "plan": {"type": "object", "description": "The travel plan organized by day"}

    },

    "required": ["is_feasible", "plan"]

   }

 }

}
